package com.giraffeslovebeauty.acmforever;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.function.BooleanSupplier;

/** Local-only checks for status surfaces, direct training routes and saved-theme deletion. */
final class PolishUiSmoke {
    private final Instrumentation test;private final Context app;private Activity activity;private String theme;
    private final ArrayList<Activity> activities=new ArrayList<>();
    private PolishUiSmoke(Instrumentation test){this.test=test;app=test.getTargetContext();}
    static void run(Instrumentation test){new PolishUiSmoke(test).run();}
    private void run(){
        Bundle output=new Bundle();int result=Activity.RESULT_CANCELED;SharedPreferences prefs=AppAppearance.prefs(app),registry=app.getSharedPreferences("local_theme_library",0);Map<String,?> original=new HashMap<>(prefs.getAll()),library=new HashMap<>(registry.getAll());ApiClient api=((AcmApplication)app.getApplicationContext()).api();String base=api.getBaseUrl();File cover=new File(app.getFilesDir(),"profile-cover.jpg");byte[] previous=read(cover);
        try{
            prefs.edit().clear().putString("theme_source","acm").putInt("theme_primary",0xffc8eb21).putInt("theme_secondary",Color.WHITE).putString("bg_mode","solid").putString("bg_source","custom").putInt("bg_color",Color.WHITE).putInt("bg_transparency",2).putInt("module_transparency",0).putInt("control_transparency",0).apply();registry.edit().clear().apply();theme=LocalThemes.save(app);
            open(OptionalTestClasses.type("ThemePreviewActivity"),LocalThemes.EXTRA,theme);await(()->description("本地主题预览，示例内容")!=null,"default preview");main(()->check(MobileStyle.ACCENT==0xffc8eb21&&MobileStyle.PANEL==Color.WHITE&&MobileStyle.BACKGROUND==0xfff4f5f7,"default theme colours"));shot("default-home-v0212.png");main(()->activity.finish());LocalThemes.delete(app,theme);theme=null;
            prefs.edit().clear().putString("api_base_url","https://polish.test.invalid").putString("bg_mode","solid").putString("bg_source","custom").putInt("bg_color",Color.RED).putInt("theme_primary",0xff83b8e5).apply();registry.edit().clear().apply();api.setBaseUrl("https://polish.test.invalid");api.setNetworkAvailable(()->false);
            open(MainActivity.class,null,null);await(()->find("社区话题")!=null,"home");test.waitForIdleSync();
            main(()->{FrameLayout frame=(FrameLayout)activity.findViewById(android.R.id.content).findViewWithTag("system_bar_surface");check(frame!=null&&frame.getChildAt(0).getTop()>0,"body is inset below system time area");Bitmap image=Bitmap.createBitmap(frame.getWidth(),frame.getHeight(),Bitmap.Config.ARGB_8888);frame.draw(new Canvas(image));int y=frame.getChildAt(0).getTop()/2;check(image.getPixel(image.getWidth()/2,y)==MobileStyle.PANEL,"status area uses toolbar surface instead of red main background");image.recycle();try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField("pageRefresh");f.setAccessible(true);((PageRefresh)f.get(activity)).actionFailure("无网络");}catch(Exception e){throw new AssertionError(e);}View title=find("API连接失败");check(title!=null,"warning visible");View banner=(View)title.getParent();check(((ViewGroup.MarginLayoutParams)banner.getLayoutParams()).topMargin>=MobileStyle.dp(app,16),"warning separated from header");});shot("system-bars-v0211.png");
            Activity source=activity;
            for(String page:new String[]{"checkin","mistakes","sheets"}){
                Instrumentation.ActivityMonitor monitor=test.addMonitor(ClubActivity.class.getName(),null,false);main(()->source.startActivity(new Intent(source,ClubActivity.class).putExtra("page",page)));activity=test.waitForMonitorWithTimeout(monitor,5000);test.removeMonitor(monitor);check(activity!=null,"training direct page opened");activities.add(activity);test.waitForIdleSync();check(find("社团训练")==null,"no extra hub on direct entry");Activity child=activity;main(()->activity.onBackPressed());test.waitForIdleSync();check(child.isFinishing()&&!source.isFinishing(),"direct training back returns to source");activity=source;
            }
            open(OptionalTestClasses.type("AdvancedAppearanceActivity"),null,null);click("主题选择");View rainbow=description("打开调色盘");main(()->check(Color.alpha(pixel(rainbow,false))==255,"rainbow is opaque before selection"));clickDescription("打开调色盘");main(()->((ColorWheel)description("调色盘，滑动选择色相和饱和度")).brightness(.64f));click("应用颜色");test.waitForIdleSync();
            main(()->{View custom=description("打开调色盘");check(custom.isSelected()&&prefs.getBoolean("theme_custom_color",false),"custom colour remains selected");check(pixel(custom,true)==prefs.getInt("theme_primary",0),"custom swatch shows chosen colour, not transparent frame");});shot("custom-colour-v0211.png");
            int primary=prefs.getInt("theme_primary",0);View originalPage=description("个性化页面");clickDescription("ACMForever辅色：樱粉");main(()->{check(description("个性化页面")==originalPage,"secondary repaints without replacing page");check(find("ACMForever主色")!=null&&find("ACMForever辅色")!=null,"two titled colour sections");check(MobileStyle.PANEL==0xffebafc5&&prefs.getInt("theme_primary",0)==primary,"secondary surface changes without changing primary");});
            clickDescription("ACMForever辅色：墨色");main(()->check(ThemePalette.contrast(MobileStyle.PANEL,MobileStyle.TEXT)>=4.49,"dark secondary keeps readable text"));clickDescription("ACMForever辅色：樱粉");clickDescription("ACMForever辅色：打开调色盘");main(()->{check(find("ACMForever辅色")!=null,"picker identifies secondary colour");((ColorWheel)description("调色盘，滑动选择色相和饱和度")).brightness(.88f);});click("应用颜色");
            main(()->{View custom=description("ACMForever辅色：打开调色盘");check(custom.isSelected()&&prefs.getBoolean("secondary_custom_color",false),"secondary custom selection persists");check(pixel(custom,true)==prefs.getInt("theme_secondary",0)&&MobileStyle.PANEL==prefs.getInt("theme_secondary",0),"custom secondary swatch and surface agree");check(prefs.getInt("theme_primary",0)==primary,"custom secondary leaves primary intact");check((activity.getWindow().getDecorView().getSystemUiVisibility()&View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR)!=0,"mid-tone secondary uses readable dark system text");custom.requestRectangleOnScreen(new Rect(0,0,custom.getWidth(),custom.getHeight()),true);});shot("secondary-colour-v0212.png");
            click("搜索栏与下方菜单背景透明度");main(()->{SeekBar bar=(SeekBar)description("按键搜索栏与下方菜单背景透明度");Bundle progress=new Bundle();progress.putFloat(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,3);check(bar.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),progress),"control opacity has user-settable stops");check(prefs.getInt("control_transparency",0)==3&&Color.alpha(MobileStyle.CHROME)==102&&Color.alpha(MobileStyle.SEARCH)==102,"control opacity applies to search and nav");check(Color.alpha(MobileStyle.MODULE)==255,"module transparency is independent");Button sample=(Button)walk(decor(),v->v instanceof Button&&"ACMForever".contentEquals(((Button)v).getText()));Bitmap bitmap=Bitmap.createBitmap(sample.getWidth(),sample.getHeight(),Bitmap.Config.ARGB_8888);sample.getBackground().setBounds(0,0,bitmap.getWidth(),bitmap.getHeight());sample.getBackground().draw(new Canvas(bitmap));check(Color.alpha(bitmap.getPixel(bitmap.getWidth()/2,bitmap.getHeight()/2))==102,"button background uses same opacity");bitmap.recycle();});shot("control-opacity-v0211.png");
            main(()->activity.onBackPressed());main(()->activity.onBackPressed());
            Bitmap image=Bitmap.createBitmap(40,40,Bitmap.Config.ARGB_8888);image.eraseColor(0xffa64050);ProfileCover.save(app,image);image.recycle();prefs.edit().putString("bg_mode","image").apply();theme=LocalThemes.save(app);LocalThemes.apply(app,theme);byte[] applied=read(cover);check(LocalThemes.prefs(app,theme).getInt("control_transparency",0)==3,"saved theme includes control opacity");
            check(LocalThemes.prefs(app,theme).getInt("theme_secondary",0)==prefs.getInt("theme_secondary",0)&&LocalThemes.prefs(app,theme).getBoolean("secondary_custom_color",false),"saved theme includes secondary and custom selection");
            click("我的主题");Activity parent=activity;Instrumentation.ActivityMonitor monitor=test.addMonitor(OptionalTestClasses.type("AdvancedAppearanceActivity").getName(),null,false);clickDescription("设置主题 未命名1");activity=test.waitForMonitorWithTimeout(monitor,5000);test.removeMonitor(monitor);check(activity!=null,"saved editor");activities.add(activity);click("删除");test.waitForIdleSync();
            main(()->{Button cancel=(Button)find("点错了喵"),remove=(Button)find("确认删除");check(cancel!=null&&remove!=null&&cancel.getHeight()==remove.getHeight()&&Math.abs(cancel.getWidth()-remove.getWidth())<=1,"equal delete/cancel buttons");check(((GradientDrawable)remove.getBackground()).getColor().getDefaultColor()==0x80ff0000,"confirmation is 50 percent red");});shot("theme-delete-v0211.png");click("点错了喵");check(LocalThemes.exists(app,theme),"cancel retains saved theme");click("删除");Activity editor=activity;click("确认删除");await(()->editor.isFinishing(),"delete completes");activity=parent;await(()->description("设置主题 未命名1")==null,"deleted theme removed from list");check(!LocalThemes.exists(app,theme)&&!LocalThemes.image(app,theme).exists(),"saved image and registry removed");check(Arrays.equals(applied,read(cover))&&prefs.getInt("control_transparency",0)==3,"applied background and settings survive deleting saved copy");
            output.putString("stream","PASS: independent primary/secondary controls, in-place preset/custom/dark secondary and saved snapshots; system status surface excludes main background, warning spacing, direct training returns without extra hub, opaque rainbow/custom swatch, independent control opacity, equal themed/50-percent-red delete confirmation, cancel and safe local deletion.\n");result=Activity.RESULT_OK;
        }catch(Throwable e){output.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));try{shot("polish-failure-v0211.png");}catch(Exception ignored){}}
        finally{for(Activity item:activities)main(()->{ModalDialogs.close(item);item.finish();});if(theme!=null&&LocalThemes.exists(app,theme))try{LocalThemes.delete(app,theme);}catch(Exception ignored){}restore(prefs,original);restore(registry,library);try{if(previous==null)cover.delete();else try(FileOutputStream out=new FileOutputStream(cover)){out.write(previous);}}catch(IOException ignored){}ProfileCover.invalidate();api.setBaseUrl(base);api.setNetworkAvailable(()->true);AppAppearance.load(app);}
        test.finish(result,output);
    }
    private int pixel(View view,boolean selected){Bitmap bitmap=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(bitmap));int color=bitmap.getPixel(bitmap.getWidth()/2,bitmap.getHeight()/2-(selected?MobileStyle.dp(app,12):0));bitmap.recycle();return color;}
    private byte[] read(File file){try{return file.isFile()?java.nio.file.Files.readAllBytes(file.toPath()):null;}catch(IOException e){throw new AssertionError(e);}}
    private void restore(SharedPreferences prefs,Map<String,?> before){SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> item:before.entrySet()){Object value=item.getValue();if(value instanceof String)edit.putString(item.getKey(),(String)value);else if(value instanceof Integer)edit.putInt(item.getKey(),(Integer)value);else if(value instanceof Boolean)edit.putBoolean(item.getKey(),(Boolean)value);else if(value instanceof Long)edit.putLong(item.getKey(),(Long)value);else if(value instanceof Float)edit.putFloat(item.getKey(),(Float)value);}edit.apply();}
    private void open(Class<?> type,String key,String value){Intent intent=new Intent().setClassName(app,type.getName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(key!=null)intent.putExtra(key,value);activity=test.startActivitySync(intent);activities.add(activity);test.waitForIdleSync();}
    private View walk(View view,java.util.function.Predicate<View> test){if(test.test(view))return view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){View found=walk(group.getChildAt(i),test);if(found!=null)return found;}}return null;}
    private View decor(){try{java.lang.reflect.Field field=ModalDialogs.class.getDeclaredField("visible");field.setAccessible(true);java.lang.ref.WeakReference<?> ref=(java.lang.ref.WeakReference<?>)((Map<?,?>)field.get(null)).get(activity);AlertDialog dialog=ref==null?null:(AlertDialog)ref.get();if(dialog!=null&&dialog.isShowing())return dialog.getWindow().getDecorView();}catch(Exception e){throw new AssertionError(e);}return activity.getWindow().getDecorView();}
    private View find(String value){return walk(decor(),v->v instanceof TextView&&value.contentEquals(((TextView)v).getText()));}
    private View description(String value){return walk(decor(),v->value.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()));}
    private void click(String value){main(()->{View target=find(value);check(target!=null,"control "+value);target.performClick();});test.waitForIdleSync();}
    private void clickDescription(String value){main(()->{View target=description(value);check(target!=null,"description "+value);target.performClick();});test.waitForIdleSync();}
    private void main(Runnable action){Throwable[] failed={null};test.runOnMainSync(()->{try{action.run();}catch(Throwable e){failed[0]=e;}});if(failed[0]!=null)throw new AssertionError(failed[0]);}
    private void await(BooleanSupplier ready,String label)throws Exception{long until=SystemClock.uptimeMillis()+5000;while(SystemClock.uptimeMillis()<until){boolean[] done={false};main(()->done[0]=ready.getAsBoolean());if(done[0]){test.waitForIdleSync();return;}Thread.sleep(60);}throw new AssertionError(label);}
    private void shot(String name)throws IOException{test.waitForIdleSync();SystemClock.sleep(350);test.waitForIdleSync();Bitmap image=test.getUiAutomation().takeScreenshot();if(image!=null){try(FileOutputStream out=new FileOutputStream(new File(app.getExternalFilesDir(null),name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
    private void check(boolean okay,String label){if(!okay)throw new AssertionError(label);}
}
